// Decides how a Bash command that posts a GitHub comment from the person's
// account gets Claude Code's footer: rewrite the command, append to the body
// file, or refuse it. Pure: register.ts does the file writes.

export const SIGNATURE_LINE = '_🤖 Addressed by [Claude Code](https://claude.com/claude-code)_'

// Any Claude Code footer ("Addressed by", "Generated with", "Generated by").
export const CLAUDE_SIGNATURE = /\[Claude Code\]\(https:\/\/claude\.(?:com|ai)\b/

export type BodyFile = { path: string; format: 'text' | 'json' }

export type SigningPlan =
  | { kind: 'pass' }
  | { kind: 'block' }
  | { kind: 'sign'; command?: string; files: BodyFile[] }

type Word = { kind: 'word'; raw: string; value: string | undefined }
type Op = { kind: 'op'; raw: string }
type Token = Word | Op

// What a comment-posting gh call reads its body (or bodies) from.
type BodySource =
  | { kind: 'inline'; word: Word; prefix: string; value: string }
  | { kind: 'file'; path: string; format: 'text' | 'json' }
  | { kind: 'unsignable' }

const COMMENT_ENDPOINT = /\b(?:pulls|issues)\/[^/\s'"]+\/(?:comments|reviews)\b|\b(?:pulls|issues)\/comments\/[^/\s'"]+/
const COMMENT_MUTATION =
  /\b(?:addPullRequestReviewThreadReply|addPullRequestReviewComment|addPullRequestReviewThread|addPullRequestReview|submitPullRequestReview|addComment|updateIssueComment|updatePullRequestReviewComment)\b/
const WRITE_METHOD = /^(?:POST|PATCH|PUT)$/i
const API_VALUE_FLAGS = new Set([
  '-X', '--method', '-f', '--raw-field', '-F', '--field', '-H', '--header', '--input',
  '-q', '--jq', '-t', '--template', '--hostname', '--cache', '-p', '--preview',
])
const HEREDOC = /<<(-?)\s*(['"]?)([A-Za-z_][A-Za-z0-9_]*)\2/g

export function planSigning(command: string): SigningPlan {
  if (CLAUDE_SIGNATURE.test(command)) return { kind: 'pass' }
  return /<<(?!<)/.test(command) ? planHeredoc(command) : planTokens(command)
}

// --- single-line and quoted commands, read word by word ----------------------

function planTokens(command: string): SigningPlan {
  const tokens = tokenize(command)
  if (!tokens) return looksLikeCommentPost(command) ? { kind: 'block' } : { kind: 'pass' }

  const sources = segments(tokens).flatMap(bodySourcesOf)
  if (sources.length === 0) return { kind: 'pass' }
  if (sources.some(source => source.kind === 'unsignable')) return { kind: 'block' }

  const files: BodyFile[] = []
  const edits = new Map<Word, string>()
  for (const source of sources) {
    if (source.kind === 'file') {
      if (!source.path.startsWith('/') || writesPath(command, source.path)) return { kind: 'block' }
      files.push({ path: source.path, format: source.format })
    } else if (source.kind === 'inline' && source.value.trim() !== '') {
      edits.set(source.word, `${source.prefix}${appendSignature(source.value)}`)
    }
  }
  if (edits.size === 0) return files.length === 0 ? { kind: 'pass' } : { kind: 'sign', files }
  if (!isRewritable(tokens)) return { kind: 'block' }
  return { kind: 'sign', command: serialize(tokens, edits), files }
}

function segments(tokens: readonly Token[]): Word[][] {
  const out: Word[][] = [[]]
  for (const token of tokens) {
    if (token.kind === 'op') out.push([])
    else out[out.length - 1]!.push(token)
  }
  return out.filter(words => words.length > 0)
}

function bodySourcesOf(words: Word[]): BodySource[] {
  let start = 0
  while (start < words.length && /^[A-Za-z_][A-Za-z0-9_]*=/.test(words[start]!.raw)) start++
  const gh = words[start]
  if (!gh || !/(?:^|\/)gh$/.test(gh.value ?? '')) return []
  const args = words.slice(start + 1)
  const [group, verb] = [args[0]?.value, args[1]?.value]
  if ((group === 'pr' || group === 'issue') && verb === 'comment') return cliBodies(args.slice(2))
  if (group === 'pr' && verb === 'review') return cliBodies(args.slice(2))
  if (group === 'api') return apiBodies(args.slice(1))
  return []
}

// `gh pr comment` / `gh issue comment` / `gh pr review`: -b/--body, -F/--body-file.
function cliBodies(args: Word[]): BodySource[] {
  const sources: BodySource[] = []
  for (let i = 0; i < args.length; i++) {
    const flag = flagOf(args, i, ['-b', '--body'], ['-F', '--body-file'])
    if (!flag) continue
    i = flag.next
    if (flag.value === undefined) sources.push({ kind: 'unsignable' })
    else if (flag.isFile) sources.push(flag.value.value === '-' ? { kind: 'unsignable' } : fileSource(flag.value, 'text'))
    else sources.push(inlineSource(flag.value, flag.prefix))
  }
  return sources
}

// `gh api <endpoint>`: body fields (`body=`, `comments[][body]=`) and --input.
function apiBodies(args: Word[]): BodySource[] {
  let endpoint: string | undefined
  let method: string | undefined
  let hasPayload = false
  const sources: BodySource[] = []
  for (let i = 0; i < args.length; i++) {
    const word = args[i]!
    const raw = word.value ?? word.raw
    const [name, attached] = splitFlag(raw)
    if (!API_VALUE_FLAGS.has(name)) {
      if (!raw.startsWith('-') && endpoint === undefined) endpoint = raw
      continue
    }
    const valueWord: Word | undefined = attached === undefined ? args[++i] : { ...word, value: word.value === undefined ? undefined : attached }
    const prefix = attached === undefined ? '' : word.value!.slice(0, word.value!.length - attached.length)
    if (name === '-X' || name === '--method') method = valueWord?.value
    if (name === '--input') {
      hasPayload = true
      sources.push(valueWord?.value === undefined || valueWord.value === '-' ? { kind: 'unsignable' } : fileSource(valueWord, 'json'))
    }
    if (name === '-f' || name === '--raw-field' || name === '-F' || name === '--field') {
      hasPayload = true
      const field = valueWord?.value
      if (field === undefined) {
        if (/(?:^['"]?|\[)body\]?=/.test(valueWord?.raw ?? '')) sources.push({ kind: 'unsignable' })
        continue
      }
      const key = field.slice(0, field.indexOf('='))
      if (key !== 'body' && !key.endsWith('[body]')) continue
      const value = field.slice(key.length + 1)
      const isTyped = name === '-F' || name === '--field'
      if (isTyped && value.startsWith('@')) {
        sources.push(value === '@-' ? { kind: 'unsignable' } : fileSource({ ...valueWord!, value: value.slice(1) }, 'text'))
      } else {
        sources.push(inlineSource(valueWord!, `${prefix}${key}=`, value))
      }
    }
  }
  if (endpoint === 'graphql') {
    const isMutation = args.some(word => COMMENT_MUTATION.test(word.value ?? word.raw))
    if (!isMutation) return []
    return sources.length > 0 ? sources : [{ kind: 'unsignable' }]
  }
  const isWrite = method === undefined ? hasPayload : WRITE_METHOD.test(method)
  return endpoint !== undefined && COMMENT_ENDPOINT.test(endpoint) && isWrite ? sources : []
}

function inlineSource(word: Word, prefix: string, value?: string): BodySource {
  const body = value ?? word.value
  return body === undefined ? { kind: 'unsignable' } : { kind: 'inline', word, prefix, value: body }
}

function fileSource(word: Word, format: 'text' | 'json'): BodySource {
  return word.value === undefined ? { kind: 'unsignable' } : { kind: 'file', path: word.value, format }
}

function splitFlag(raw: string): [string, string | undefined] {
  if (raw.startsWith('--')) {
    const at = raw.indexOf('=')
    return at < 0 ? [raw, undefined] : [raw.slice(0, at), raw.slice(at + 1)]
  }
  if (/^-[A-Za-z]./.test(raw)) return [raw.slice(0, 2), raw.slice(2).replace(/^=/, '')]
  return [raw, undefined]
}

// The value of an inline flag (`--body x`, `--body=x`, `-bx`) or a file flag.
function flagOf(
  args: Word[],
  i: number,
  inline: readonly string[],
  file: readonly string[],
): { value: Word | undefined; prefix: string; isFile: boolean; next: number } | undefined {
  const word = args[i]!
  const [name, attached] = splitFlag(word.value ?? word.raw)
  const isFile = file.includes(name)
  if (!isFile && !inline.includes(name)) return undefined
  if (attached === undefined) return { value: args[i + 1], prefix: '', isFile, next: i + 1 }
  if (word.value === undefined) return { value: undefined, prefix: '', isFile, next: i }
  const prefix = word.value.slice(0, word.value.length - attached.length)
  return { value: { ...word, value: attached }, prefix, isFile, next: i }
}

function appendSignature(body: string): string {
  return `${body.replace(/\s+$/, '')}\n\n${SIGNATURE_LINE}`
}

// A body file written by the same command is not there yet to be signed.
function writesPath(command: string, path: string): boolean {
  const escaped = path.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
  return new RegExp(`(?:>|\\btee\\s+(?:-a\\s+)?)\\s*['"]?${escaped}`).test(command)
}

function isRewritable(tokens: readonly Token[]): boolean {
  return tokens.every(token =>
    token.kind === 'word' ? token.value !== undefined : [';', '\n', '&&', '||', '|'].includes(token.raw),
  )
}

function serialize(tokens: readonly Token[], edits: ReadonlyMap<Word, string>): string {
  return tokens
    .map(token => {
      if (token.kind === 'op') return token.raw === '\n' ? '\n' : token.raw
      const value = edits.get(token) ?? token.value!
      return `'${value.replace(/'/g, `'\\''`)}'`
    })
    .join(' ')
    .replace(/ ?\n ?/g, '\n')
}

// A shell lexer for commands with no heredoc: words with their literal value
// (undefined when they expand: $, backticks, globs, ~), and the operators
// between them. Undefined when a quote or expansion is left open.
function tokenize(command: string): Token[] | undefined {
  const tokens: Token[] = []
  const n = command.length
  let i = 0
  while (i < n) {
    const c = command[i]!
    if (c === ' ' || c === '\t') { i++; continue }
    if (c === '\\' && command[i + 1] === '\n') { i += 2; continue }
    if (c === '#') { while (i < n && command[i] !== '\n') i++; continue }
    if (c === '\n' || c === ';' || c === '<' || c === '>' || c === '(' || c === ')') {
      tokens.push({ kind: 'op', raw: c }); i++; continue
    }
    if (c === '&' || c === '|') {
      const pair = command.slice(i, i + 2)
      const raw = pair === '&&' || pair === '||' ? pair : c
      tokens.push({ kind: 'op', raw }); i += raw.length; continue
    }
    const start = i
    let value = ''
    let isLiteral = true
    while (i < n) {
      const ch = command[i]!
      if (' \t\n;&|<>()'.includes(ch)) break
      if (ch === "'") {
        const end = command.indexOf("'", i + 1)
        if (end < 0) return undefined
        value += command.slice(i + 1, end); i = end + 1; continue
      }
      if (ch === '"') {
        i++
        let isClosed = false
        while (i < n) {
          const d = command[i]!
          if (d === '"') { i++; isClosed = true; break }
          if (d === '\\' && i + 1 < n && '"\\$`\n'.includes(command[i + 1]!)) {
            if (command[i + 1] !== '\n') value += command[i + 1]
            i += 2; continue
          }
          if (d === '$' || d === '`') {
            isLiteral = false
            i = skipExpansion(command, i)
            if (i < 0) return undefined
            continue
          }
          value += d; i++
        }
        if (!isClosed) return undefined
        continue
      }
      if (ch === '\\') {
        if (i + 1 >= n) return undefined
        if (command[i + 1] !== '\n') value += command[i + 1]
        i += 2; continue
      }
      if (ch === '$' || ch === '`') {
        isLiteral = false
        i = skipExpansion(command, i)
        if (i < 0) return undefined
        continue
      }
      if ('*?[]'.includes(ch) || (ch === '~' && i === start)) isLiteral = false
      value += ch; i++
    }
    const raw = command.slice(start, i)
    // `{owner}` is literal to the shell; `{a,b}` and `{1..3}` expand.
    if (/\{[^}]*(?:,|\.\.)[^}]*\}/.test(raw)) isLiteral = false
    tokens.push({ kind: 'word', raw, value: isLiteral ? value : undefined })
  }
  return tokens
}

// Index just past the expansion starting at `i` ($name, ${..}, $(..), `..`, $'..'), or -1.
function skipExpansion(command: string, i: number): number {
  if (command[i] === '`') {
    const end = command.indexOf('`', i + 1)
    return end < 0 ? -1 : end + 1
  }
  const next = command[i + 1]
  if (next === "'") {
    const end = command.indexOf("'", i + 2)
    return end < 0 ? -1 : end + 1
  }
  if (next === '{') {
    const end = command.indexOf('}', i + 2)
    return end < 0 ? -1 : end + 1
  }
  if (next === '(') {
    let depth = 0
    for (let j = i + 1; j < command.length; j++) {
      const ch = command[j]!
      if (ch === "'") { j = command.indexOf("'", j + 1); if (j < 0) return -1; continue }
      if (ch === '"') { j = command.indexOf('"', j + 1); if (j < 0) return -1; continue }
      if (ch === '(') depth++
      if (ch === ')' && --depth === 0) return j + 1
    }
    return -1
  }
  let j = i + 1
  while (j < command.length && /[A-Za-z0-9_@*#?$!-]/.test(command[j]!)) j++
  return j === i + 1 ? i + 1 : j
}

// --- commands with a heredoc: the footer goes in as the heredoc's last line ---

function looksLikeCommentPost(command: string): boolean {
  if (/\bgh\s+(?:pr|issue)\s+comment\b/.test(command)) return true
  if (/\bgh\s+pr\s+review\b/.test(command) && /\s(?:-b|--body|-F|--body-file)(?:[\s=]|$)/.test(command)) return true
  if (!/\bgh\s+api\b/.test(command)) return false
  if (/\bgraphql\b/.test(command)) return COMMENT_MUTATION.test(command)
  const isWrite = /\s(?:-f|-F|--field|--raw-field|--input)[\s=]|\s(?:-X|--method)[\s=]*['"]?(?:POST|PATCH|PUT)\b/i.test(command)
  return isWrite && COMMENT_ENDPOINT.test(command)
}

// The command with each heredoc's body taken out: text a heredoc writes (a
// script, a doc that mentions gh) is not a command the shell runs.
function withoutHeredocBodies(command: string): string {
  let out = ''
  let at = 0
  for (const heredoc of command.matchAll(HEREDOC)) {
    if (heredoc.index < at) continue
    const lineEnd = command.indexOf('\n', heredoc.index)
    if (lineEnd < 0) break
    const [, dash, , delimiter] = heredoc
    const terminator = new RegExp(`^${dash ? '\\t*' : ''}${delimiter}$`, 'm')
    const found = terminator.exec(command.slice(lineEnd + 1))
    if (!found) break
    out += command.slice(at, lineEnd + 1)
    at = lineEnd + 1 + found.index
  }
  return out + command.slice(at)
}

function planHeredoc(command: string): SigningPlan {
  const shellText = withoutHeredocBodies(command)
  if (!looksLikeCommentPost(shellText)) return { kind: 'pass' }
  const heredocs = [...command.matchAll(HEREDOC)]
  if (heredocs.length !== 1) return { kind: 'block' }
  const heredoc = heredocs[0]!
  const lineStart = command.lastIndexOf('\n', heredoc.index) + 1
  const lineEnd = command.indexOf('\n', heredoc.index)
  if (lineEnd < 0 || !feedsBody(shellText, command.slice(lineStart, lineEnd))) return { kind: 'block' }

  const [, dash, , delimiter] = heredoc
  const terminator = new RegExp(`^${dash ? '\\t*' : ''}${delimiter}$`, 'm')
  const rest = command.slice(lineEnd + 1)
  const found = terminator.exec(rest)
  if (!found) return { kind: 'block' }
  const at = lineEnd + 1 + found.index
  const body = command.slice(lineEnd + 1, at)
  if (body.trim() === '') return { kind: 'block' }
  return { kind: 'sign', command: `${command.slice(0, lineEnd + 1)}${appendSignature(body)}\n${command.slice(at)}`, files: [] }
}

// Whether the heredoc on this line is the comment's body: substituted into
// --body / a body field, piped as --body-file - / body=@-, or written to the
// file the post reads.
function feedsBody(command: string, line: string): boolean {
  const field = String.raw`(?:-f|-F|--field|--raw-field)\s+['"]?(?:[\w[\]]*\[)?body\]?=`
  if (new RegExp(String.raw`(?:--body(?:\s+|=)|-b\s+|${field})"?\$\(\s*cat\s+<<`).test(line)) return true
  if (/(?:--body-file|\s-F)(?:\s+|=)-(?:\s|$)/.test(command) || new RegExp(`${field}@-`).test(command)) return true
  const fieldFile = new RegExp(`${field}@['"]?([^\\s'"]+)`).exec(command)?.[1]
  const cliFile = /(?:--body-file|\s-F)(?:\s+|=)['"]?([^\s'"=]+)['"]?(?:\s|$)/.exec(command)?.[1]
  const file = fieldFile ?? cliFile
  return file !== undefined && file !== '-' && writesPath(line, file)
}

// --- --input JSON: sign `body` and each review comment's `body` --------------

export function signJsonPayload(text: string): string | undefined {
  let payload: unknown
  try {
    payload = JSON.parse(text)
  } catch {
    return undefined
  }
  if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) return undefined
  const record = payload as { body?: unknown; comments?: unknown }
  const sign = (body: unknown): unknown => (typeof body === 'string' && body.trim() !== '' ? appendSignature(body) : body)
  const comments = Array.isArray(record.comments)
    ? record.comments.map(comment =>
        typeof comment === 'object' && comment !== null ? { ...comment, body: sign((comment as { body?: unknown }).body) } : comment,
      )
    : record.comments
  return JSON.stringify({ ...record, body: sign(record.body), ...(comments === undefined ? {} : { comments }) })
}

export function signTextBody(text: string): string {
  return `${appendSignature(text)}\n`
}

